function exportCSV(data, factory, date) {
    const header = [
        'Round',
        'QR Point',
        'Guard',
        'Scan Time',
        'Status',
        'Lat',
        'Lon'
    ];
    const rows = data.map((r)=>[
            r.round,
            `"${r.qr_name}"`,
            `"${r.guard_name || ''}"`,
            r.scan_time ? fmtTime(r.scan_time) : '',
            r.status,
            r.lat || '',
            r.lon || ''
        ]);
    const csv = [
        header,
        ...rows
    ].map((r)=>r.join(',')).join('\n');
    const blob = new Blob([
        csv
    ], {
        type: 'text/csv'
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `patrol_${factory}_${date}.csv`;
    a.click();
    URL.revokeObjectURL(url);
}
